import math


def _num(d, key, default=0.0):
    if not isinstance(d, dict):
        return float(default)
    v = d.get(key, default)
    if v is None:
        return float(default)
    try:
        f = float(v)
    except (TypeError, ValueError):
        return float(default)
    if math.isnan(f) or math.isinf(f):
        return float(default)
    return f


def _clamp(x, lo, hi):
    return max(lo, min(hi, x))


def _smoothed_post_spawn_impact(states: list[dict]) -> float:
    """Compute 3-tick smoothed acceleration deviation from 1g after t > 0.30s to ignore the t=0 spawn drop and 1-tick chatter."""
    post = [s for s in states if _num(s, "t", 0.0) > 0.30]
    if len(post) < 3:
        return 0.0
    mags = []
    for s in post:
        acc = s.get("accel")
        if isinstance(acc, (list, tuple)) and len(acc) == 3:
            norm_a = math.sqrt(sum(float(c) * float(c) for c in acc))
            mags.append(abs(norm_a - 9.81))
    if len(mags) < 3:
        return 0.0
    peak = 0.0
    for i in range(len(mags) - 2):
        win_avg = (mags[i] + mags[i + 1] + mags[i + 2]) / 3.0
        peak = max(peak, win_avg)
    return peak


def score(ep: dict) -> float:
    outcome = ep.get("outcome", "")
    success = bool(ep.get("success", False) or outcome == "success")
    fell = bool(ep.get("fell", False) or outcome == "fell")
    collided = bool(ep.get("collided", False) or outcome == "collided")
    near_miss = bool(ep.get("near_miss", False) or outcome == "near_miss")
    stalled = bool(ep.get("stalled", False) or outcome == "stalled")
    timeout = bool(
        outcome == "timeout"
        or (not success and not fell and not collided and not near_miss and not stalled)
    )

    duration = max(0.0, _num(ep, "duration", 0.0))
    max_tilt_deg = max(0.0, _num(ep, "max_tilt_deg", 0.0))
    jerk = max(0.0, _num(ep, "jerk", 0.0))
    min_clearance = _num(ep, "min_clearance", 0.0) if ep.get("min_clearance") is not None else None

    states = ep.get("states") or []
    n = len(states)

    # Ignore the t < 0.30s 2cm spawn-drop artifact (~32.6 m/s^2) when evaluating driving shock
    drive_impact = _smoothed_post_spawn_impact(states)
    hard_contact = collided or fell or (max_tilt_deg > 15.0) or (drive_impact > 12.0)
    clean_success = success and not hard_contact and not near_miss and not stalled

    # Estimate obstacle x and goal x from states (obs dict reports dx in robot frame)
    start_x = _num(states[0], "x", -0.8) if n > 0 else -0.8
    final_x = _num(states[-1], "x", start_x) if n > 0 else (3.0 if success else start_x)
    max_x = max((_num(s, "x", start_x) for s in states), default=final_x)

    obs_x_est = 1.5
    if n > 0 and isinstance(states[0].get("obs"), dict):
        obs0 = states[0]["obs"]
        obs_x_est = start_x + _num(obs0, "dx", 2.3)
    goal_x_est = obs_x_est + 1.5
    target_span = max(1.0, goal_x_est - start_x)

    progress_frac = _clamp((final_x - start_x) / target_span, -0.2, 1.0)
    passed_obstacle = final_x > (obs_x_est + 0.15)

    total = 0.0

    # 1. Terminal outcome rewards and penalties
    if clean_success:
        total += 160.0
        if min_clearance is not None and min_clearance >= 0.15:
            total += _clamp(14.0 - 1.4 * max(0.0, duration - 9.5), 0.0, 14.0)
    elif success:
        total += 60.0

    if fell:
        total -= 220.0
    if collided:
        total -= 220.0
    if near_miss:
        total -= 140.0
    if stalled:
        total -= 210.0
    if timeout and not success:
        total -= 130.0

    # 2. Progress shaping
    if success:
        total += 40.0
    elif passed_obstacle and not (collided or fell):
        total += 20.0 * progress_frac
    else:
        shortfall = _clamp(1.0 - progress_frac, 0.0, 1.2)
        total -= 45.0 * shortfall

    # Penalize backtracking
    backtrack_m = max(0.0, max_x - final_x)
    total -= 25.0 * _clamp(backtrack_m, 0.0, 1.5)

    # 3. Obstacle clearance: only credit clearance if the robot actually reached/passed the obstacle
    if min_clearance is not None:
        if passed_obstacle or collided or near_miss or (max_x >= obs_x_est - 0.35):
            if min_clearance < 0.04:
                total -= 140.0 + 1800.0 * (0.04 - max(0.0, min_clearance))
            elif min_clearance < 0.12:
                deficit = (0.12 - min_clearance) / 0.08
                total -= 35.0 + 95.0 * (deficit ** 2)
            elif min_clearance < 0.30:
                deficit = (0.30 - min_clearance) / 0.18
                total -= 35.0 * (deficit ** 2)
            elif clean_success:
                total += 50.0 * _clamp((min_clearance - 0.30) / 0.35, 0.0, 1.0)
        else:
            # Never reached the obstacle (crawled/parked upstream): no fake clearance bonus
            total -= 35.0

    # 4. Dynamic impact, tilt, and smoothness
    if drive_impact > 4.0:
        imp_ex = drive_impact - 4.0
        total -= _clamp(4.0 * imp_ex + 0.3 * (imp_ex ** 2), 0.0, 100.0)

    if max_tilt_deg > 8.0:
        tilt_ex = max_tilt_deg - 8.0
        total -= _clamp(2.5 * tilt_ex + 0.2 * (tilt_ex ** 2), 0.0, 80.0)

    if n > 0:
        crawl_ticks = 0
        reverse_pen = 0.0
        roll_pen = 0.0
        for s in states:
            spd = _num(s, "speed", 0.0)
            vx = _num(s, "vx", spd)
            cmd_v = _num(s, "cmd_v", 0.0)
            roll = abs(_num(s, "roll_deg", 0.0))
            if spd < 0.16 or vx < 0.12:
                crawl_ticks += 1
            if cmd_v < -0.02 or vx < -0.02:
                reverse_pen += abs(min(cmd_v, vx))
            if roll > 3.0:
                roll_pen += (roll - 3.0)

        crawl_ratio = crawl_ticks / float(n)
        if not success:
            total -= 55.0 * crawl_ratio
        else:
            total -= 15.0 * crawl_ratio
        total -= _clamp(10.0 * reverse_pen / float(n), 0.0, 25.0)
        total -= _clamp(4.0 * roll_pen / float(n), 0.0, 25.0)

    if jerk > 0.4:
        j_ex = jerk - 0.4
        total -= _clamp(10.0 * j_ex + 3.0 * (j_ex ** 2), 0.0, 35.0)
    elif clean_success:
        total += 6.0 * ((0.4 - jerk) / 0.4)

    return float(total)
